SELECT name, price
FROM products
WHERE price > (SELECT AVG(price) FROM products);

SELECT p.name
FROM products p
WHERE NOT EXISTS (
  SELECT 1 FROM orders o
  WHERE o.product_id = p.id AND o.quantity > 1
);

SELECT ROUND(AVG(line_total), 2) AS avg_order_value
FROM (
  SELECT p.price * o.quantity AS line_total
  FROM orders o
  JOIN products p ON p.id = o.product_id
) AS lines;

SELECT name, price
FROM products
WHERE price < (SELECT MIN(price) FROM products WHERE category = 'Electronics');
